{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Sound Baths for practical rest</title>
  <meta name="description" content="Group gatherings, private sessions, and gentle programs to help you land, breathe, and return with steadiness." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav">
        <a href="/events.html">Gatherings</a>
        <a href="/private-sessions.html">Private</a>
        <a href="/pricing.html">Invest</a>
        <a href="/about.html">Essence</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="/book.html">{{PRIMARY_CTA_LABEL}}</a>
        <a class="reach" href="/contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero" id="hero">
      <svg class="hero-pattern" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 200">
        <defs>
          <pattern id="p" width="60" height="60" patternUnits="userSpaceOnUse">
            <rect width="60" height="60" fill="#f6f5f3"></rect>
            <path d="M0 30 C15 10 45 50 60 30" stroke="#efeae6" stroke-width="2" fill="none" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#p)"></rect>
      </svg>
      <div class="wrap hero-body">
        <div class="hero-copy">
          <h1 class="title">A room tuned for slowing — sound offered, not served</h1>
          <p class="lead">A short invitation to breathe more plainly, to be held by tones that steady rather than carry you away. Small groups, private appointments, and guided blends for everyday rest.</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="/events.html">View gatherings</a>
          </div>
          <p class="contact">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <aside class="hero-panel">
          <div class="next-event" id="nextEvent">
            <small>Next gathering</small>
            <div class="event-card">
              <div class="date" id="nextEventDate">—</div>
              <div>
                <strong id="nextEventTitle">Loading...</strong>
                <div class="meta"><span id="nextEventLoc">{{CITY}}, {{STATE}}</span></div>
                <a class="btn small" href="/events.html">Reserve a seat</a>
              </div>
            </div>
            <a class="view-calendar" href="/events.html">Full calendar →</a>
          </div>

          <div class="mixer" id="mixer">
            <small>Choose a sound preference</small>
            <div class="mixer-controls">
              <button data-level="gentle" class="mixer-btn active">Gentle</button>
              <button data-level="medium" class="mixer-btn">Medium</button>
              <button data-level="intense" class="mixer-btn">Intense</button>
            </div>
            <div class="mixer-recommendation" id="mixerRecommendation">
              <h4>Recommendation</h4>
              <div id="recommendationList">
                <!-- populated by JS -->
              </div>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <section class="myth-truth wrap" id="myth">
      <h2>Myth &amp; clarity</h2>
      <ul class="myth-list">
        <li>
          <strong>Myth:</strong> Sound will sweep you into trance.
          <p><strong>Truth:</strong> Our sessions are anchored to breath and posture so you return steady; guidance is practical and paced.</p>
        </li>
        <li>
          <strong>Myth:</strong> Louder equals deeper.
          <p><strong>Truth:</strong> Intensity is calibrated to the room and intention; depth arises from attention, not volume.</p>
        </li>
      </ul>
    </section>

    <section class="pillars wrap" id="pillars">
      <h2>How we shape an evening</h2>
      <div class="pillar-grid">
        <article>
          <h3>Gather</h3>
          <p>Quiet arrival, brief orientation, and a shared container to land into the moment.</p>
        </article>
        <article>
          <h3>Tone</h3>
          <p>Layered instruments and breath-led pacing. Choices for gentle, medium, or tactile intensity.</p>
        </article>
        <article>
          <h3>Return</h3>
          <p>Time to reorient with short grounding cues so you leave able to move into errands, meetings, or sleep.</p>
        </article>
      </div>
    </section>

    <section class="case-notes wrap" id="proof">
      <h2>Proof gallery</h2>
      <p class="sub">Voices from our room and the credentials that invite trust.</p>

      <div class="proof-outer">
        <div class="testimonials" id="testimonials">
          <!-- testimonials rotated by JS -->
          <blockquote class="testimonial">Loading testimonials…</blockquote>
        </div>

        <div class="badges" id="badges" aria-hidden="false">
          <div class="badge" data-tip="Years of community classes">Community 6 yrs</div>
          <div class="badge" data-tip="Trained in somatic facilitation">Somatic-trained</div>
          <div class="badge" data-tip="Local health partnership">Partner: Healing Collective</div>
        </div>
      </div>

      <div class="cred-tools">
        <small>Hover a badge to read more.</small>
        <div class="tooltip" id="badgeTip" role="status" aria-live="polite"></div>
      </div>
    </section>

    <section class="faq wrap" id="faq">
      <h2>Common questions</h2>
      <details>
        <summary>Is this safe if I have health concerns?</summary>
        <p>We include a contraindications note in every booking. If you are pregnant, have epilepsy, recent head injury, implanted medical devices, or uncontrolled cardiovascular conditions, please consult your clinician before attending. Reach out via {{EMAIL}} to discuss individual needs.</p>
      </details>

      <details>
        <summary>How long are gatherings?</summary>
        <p>Group gatherings typically run 60–75 minutes; private sessions vary. See <a href="/events.html">events</a> for specifics.</p>
      </details>
    </section>

    <section class="cta wrap" id="cta">
      <div class="cta-panel">
        <h2>Book a seat or a private hour</h2>
        <p>Reserve a place in our public gatherings or arrange a tailored session for a household, team, or ceremony.</p>
        <div class="cta-actions">
          <a class="btn primary" href="/book.html">Reserve now</a>
          <a class="btn ghost" href="/contact.html">Ask a question</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer wrap">
    <nav class="footer-nav">
      <a href="/about.html">About</a>
      <a href="/pricing.html">Pricing</a>
      <a href="/faq.html">FAQ</a>
      <a href="/contact.html">Contact</a>
    </nav>
    <p class="disclaimer">Contraindications: People with epilepsy, active psychosis, uncontrolled heart conditions, or recent head/ear surgery should consult a clinician prior to attending. This site does not replace medical advice.</p>
    <p class="copyright">© <span id="year"></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
