{"path":"assets/css/styles.css","content":"/* Minimal poetic stylesheet for sound bath template */
:root{
  --bg:#fbfaf8;--muted:#6b6b67;--accent:#4a6b6b;--card:#fff;--glass:rgba(255,255,255,0.6);
  --radius:10px;--maxw:1100px;--mono:system-ui,Segoe UI,Roboto,"Helvetica Neue",Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:var(--mono);background:var(--bg);color:#222;line-height:1.5}
.wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.9),transparent);backdrop-filter:blur(2px);position:sticky;top:0;z-index:40}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none}
.main-nav a{margin:0 8px;color:var(--muted);text-decoration:none}
.main-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px;text-decoration:none}
.hero{position:relative;padding:48px 0 32px;background-image:url('/assets/img/pattern.svg');background-size:cover}
.hero-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.08}
.hero-body{display:flex;gap:28px;align-items:flex-start}
.hero-copy{flex:1;color:#111}
.title{font-size:28px;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-actions .btn{margin-right:10px}
.btn{display:inline-block;padding:10px 14px;border-radius:8px;text-decoration:none;color:inherit;border:1px solid rgba(0,0,0,0.06)}
.btn.primary{background:var(--accent);color:#fff;border:none}
.btn.ghost{background:transparent}
.btn.small{font-size:13px;padding:6px 8px}
.hero-panel{width:320px}
.next-event{background:var(--card);padding:12px;border-radius:12px;box-shadow:0 6px 20px rgba(31,31,31,0.06);margin-bottom:12px}
.event-card{display:flex;gap:12px;align-items:center}
.event-card .date{background:linear-gradient(180deg,#f6f3f1,#efe9e6);padding:10px;border-radius:8px;font-weight:700}
.mixer{background:var(--card);padding:12px;border-radius:12px}
.mixer-controls{display:flex;gap:8px;margin:8px 0}
.mixer-btn{flex:1;padding:8px;border-radius:8px;border:1px solid #e6e6e4;background:#fff}
.mixer-btn.active{background:var(--accent);color:#fff}
.mixer-recommendation{margin-top:10px}
.mixer-recommendation h4{margin:0 0 6px}
.myth-truth{background:transparent;padding-bottom:0}
.myth-list{list-style:none;padding:0;margin:12px 0}
.pillars .pillar-grid{display:flex;gap:18px}
.pillars article{background:var(--card);padding:16px;border-radius:10px;flex:1}
.case-notes .proof-outer{display:flex;gap:18px;align-items:flex-start}
.testimonials{flex:1;background:var(--card);padding:18px;border-radius:12px;min-height:120px}
.testimonial{font-style:italic}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:var(--glass);padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.03);cursor:default}
.tooltip{min-height:32px;color:var(--muted);padding:8px}
.faq details{background:var(--card);padding:12px;border-radius:10px;margin:8px 0}
.cta-panel{background:var(--accent);color:#fff;padding:20px;border-radius:12px;text-align:center}
.footer-nav{display:flex;gap:12px;flex-wrap:wrap}
.site-footer{padding:28px 0}
.disclaimer{margin-top:12px;color:var(--muted);font-size:13px}
@media (max-width:900px){
  .hero-body{flex-direction:column}
  .hero-panel{width:100%}
  .pillars .pillar-grid{flex-direction:column}
  .case-notes .proof-outer{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Basic utilities
  function qs(sel,root=document){return root.querySelector(sel)}
  function qsa(sel,root=document){return Array.from(root.querySelectorAll(sel))}

  // Set year in footer
  qs('#year').textContent = new Date().getFullYear()

  // Sample events for next-event module + calendar list (used on events page too)
  var events = [
    {id:1,title:'Evening Resonance — Community',date:'2026-03-02T18:30:00',loc:'Studio A'},
    {id:2,title:'Midday Short Set',date:'2026-03-05T12:15:00',loc:'Studio B'},
    {id:3,title:'Weekend Deep',date:'2026-03-07T10:00:00',loc:'Studio A'},
  ]

  // Next upcoming event
  function nextEvent(now, list){
    var n = list.slice().sort((a,b)=>new Date(a.date)-new Date(b.date)).find(e=>new Date(e.date)>now)
    return n||list[0]
  }
  var upcoming = nextEvent(new Date(), events)
  if(upcoming){
    var d = new Date(upcoming.date)
    qs('#nextEventDate').textContent = d.toLocaleDateString(undefined,{month:'short',day:'numeric'}) + ' • ' + d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})
    qs('#nextEventTitle').textContent = upcoming.title
    qs('#nextEventLoc').textContent = upcoming.loc
  }

  // Sound preference mixer
  var recommendations = {
    gentle:[
      {name:'Resting Field — 45 min',desc:'Low-sustain tones for gradual softening.'},
      {name:'Evening Ease — 60 min',desc:'Slow breath cues, subtle harmonic layers.'}
    ],
    medium:[
      {name:'Grounded Wave — 60 min',desc:'Moderate layering, movement invitations.'},
      {name:'Midday Reset — 40 min',desc:'Shorter session with rhythmic anchors.'}
    ],
    intense:[
      {name:'Tactile Resonance — 75 min',desc:'Denser sustain and tactile elements.'},
      {name:'Deep Focus Intensive — 90 min',desc:'For those seeking pronounced vibratory textures.'}
    ]
  }

  function renderRecommendation(level){
    var list = recommendations[level]||[]
    var out = list.map(function(p){
      return '<div class="rec"><strong>'+escapeHtml(p.name)+'</strong><div class="muted">'+escapeHtml(p.desc)+'</div></div>'
    }).join('')
    qs('#recommendationList').innerHTML = out
  }

  function escapeHtml(s){return String(s).replace(/[&<>\"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}

  // Attach mixer buttons
  var mixer = qs('#mixer')
  if(mixer){
    qsa('.mixer-btn', mixer).forEach(function(btn){
      btn.addEventListener('click', function(){
        qsa('.mixer-btn', mixer).forEach(b=>b.classList.remove('active'))
        btn.classList.add('active')
        var level = btn.getAttribute('data-level')
        renderRecommendation(level)
        // announce to screen readers
        qs('#mixerRecommendation').setAttribute('aria-live','polite')
      })
    })
    // initialize
    renderRecommendation('gentle')
  }

  // Proof gallery: rotating testimonials
  var testimonials = [
    {text:'I left with a steadier pulse and the ability to breathe through a busy evening. The facilitation framed each tone practically.',author:'— Alina'},
    {text:'An uncluttered practice. Clear instructions, gentle instruments, and a simple way back to ordinary tasks.',author:'— Marcus'},
    {text:'We booked a private session for our team; it helped everyone move through a long day with more composure.',author:'— Council of Makers'}
  ]
  var ti = 0
  function showTestimonial(i){
    var t = testimonials[i%testimonials.length]
    qs('#testimonials .testimonial').innerHTML = '"'+escapeHtml(t.text)+'"<footer>'+escapeHtml(t.author)+'</footer>'
  }
  // initial
  showTestimonial(0)
  setInterval(function(){ti++;showTestimonial(ti)},4500)

  // Badges tooltip
  var badgeTip = qs('#badgeTip')
  qsa('.badge').forEach(function(b){
    b.addEventListener('mouseenter', function(){badgeTip.textContent = b.getAttribute('data-tip')})
    b.addEventListener('focus', function(){badgeTip.textContent = b.getAttribute('data-tip')})
    b.addEventListener('mouseleave', function(){badgeTip.textContent = ''})
  })

  // Accessibility: keyboard controls for testimonials (left/right)
  document.addEventListener('keydown', function(e){
    if(e.key==='ArrowRight'){ti++;showTestimonial(ti)}
    if(e.key==='ArrowLeft'){ti--;showTestimonial(ti)}
  })

  // Simple hydration for links to pages in sitemap (not exhaustive)
  // Build a minimal in-memory calendar list for events page if the page exists
  if(typeof window.populateEventCalendar === 'function'){
    window.populateEventCalendar(events)
  }
})();"} 
